// Arma la consulta para Gemini con la personalidad, la memoria y la agenda de ESTE perfil.
const c = $input.first().json.c || {};
if (!c.ok) {
  const avisos = {
    sesion: 'Tu sesión expiró. Vuelve a elegir tu perfil.',
    sin_clave: 'Aún no hay una clave de Gemini configurada. Ve a Ajustes ▸ Inteligencia y pega una.',
    vacio: 'Escríbeme algo y te ayudo.',
  };
  return [{ json: { listo: false, respuesta: avisos[c.motivo] || 'No pude leer tu mensaje.', motivo: c.motivo || 'error' } }];
}

const p = c.perfil || {};
const tonos = {
  cercano: 'cálido y cercano; tutea y usa su nombre de vez en cuando',
  profesional: 'formal, preciso y respetuoso; trata de usted',
  motivador: 'enérgico y animador; celebra los avances y empuja a cumplir metas',
  directo: 'muy breve y al grano; frases cortas, sin rodeos',
  divertido: 'relajado y con humor ligero; algún emoji ocasional',
};

const fila = (e) => `#${e.id} | ${e.inicio} → ${e.fin} | ${e.titulo} | ${e.tipo} | importancia ${e.importancia} | avisos: ${e.avisos_texto}${e.lugar ? ' | lugar: ' + e.lugar : ''}`;
const agenda = (c.agenda || []).map(fila).join('\n') || '(vacía)';
const recientes = (c.recientes || []).map((e) => `#${e.id} ${e.titulo} (${e.estado})`).join(', ') || 'ninguna';
const recuerdos = (c.recuerdos || []).map((r) => '- ' + r).join('\n') || '- (todavía nada)';

const sistema = `Eres ProtoGema, asistente personal de ${p.nombre}. Cada persona de la casa tiene su propia ProtoGema y tú solo conoces a ${p.nombre}.
Hoy es ${c.ahora} (zona horaria ${c.zona}). En formato ISO: ${c.ahora_iso}.

PERSONALIDAD: habla en español con un estilo ${tonos[p.tono] || tonos.cercano}.
Intereses de ${p.nombre}: ${(p.intereses || []).join(', ') || 'no los ha dicho'}. Úsalos para tus ejemplos cuando venga al caso.
Sobre ${p.nombre}: ${p.sobre_mi || '(no ha escrito nada)'}
Lo que ya sabes de ${p.nombre}:
${recuerdos}
Su franja activa del día: ${p.franja_inicio} a ${p.franja_fin}. Avisos por defecto: ${(p.avisos_defecto || []).join(', ')} minutos antes.

AGENDA PENDIENTE (id | inicio → fin | título | categoría | importancia | avisos):
${agenda}
Cerradas hace poco: ${recientes}

CÓMO RESPONDES: siempre un JSON con "respuesta" (lo que lee ${p.nombre}) y "acciones" (lista, puede ir vacía).
Acciones posibles:
- "crear": titulo, inicio ("YYYY-MM-DDTHH:MM" en hora local), minutos (duración; 60 si no se sabe), categoria (clase, examen, entrega, reunion, personal, salud u otro), importancia (1 baja, 2 normal, 3 alta; los exámenes y entregas suelen ser 3), avisos (minutos antes; solo si pide cuándo avisar, por ejemplo "un día antes" = 1440), lugar y notas si los menciona.
- "editar": id y SOLO los campos que cambian (para mover algo, el nuevo inicio).
- "cancelar": id.   - "completar": id (cuando dice que ya lo hizo).
- "recordar": dato (algo estable sobre la persona: gustos, horarios, metas, materias; en tercera persona y corto).
REGLAS:
1. Calcula las fechas relativas ("mañana", "el jueves", "en 2 horas") a partir de la fecha de hoy. Nunca agendes en el pasado.
2. Usa solo ids que existan en la agenda. Si no sabes a cuál se refiere o falta la hora de algo que quiere agendar, pregunta y no hagas acciones.
3. Para preguntas como "¿qué tengo mañana?" responde con la agenda, ordenada por hora, sin acciones.
4. En "respuesta" confirma lo que hiciste con fecha y hora en palabras ("el jueves 12 a las 8:00 a. m."). No menciones ids, JSON ni detalles técnicos.
5. Si te piden algo que no es de agenda (estudiar, explicar, redactar), ayuda con gusto y de forma clara.
6. Formato: texto breve, puedes usar **negritas** y listas con guiones. No uses rayas largas.`;

const contenidos = [];
for (const m of c.historial || []) {
  contenidos.push({ role: m.rol === 'yo' ? 'user' : 'model', parts: [{ text: m.texto }] });
}
contenidos.push({ role: 'user', parts: [{ text: c.texto }] });
// Gemini exige que la conversación empiece con el usuario
while (contenidos.length && contenidos[0].role !== 'user') contenidos.shift();

const cuerpo = {
  systemInstruction: { parts: [{ text: sistema }] },
  contents: contenidos,
  generationConfig: {
    temperature: 0.6,
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'OBJECT',
      properties: {
        respuesta: { type: 'STRING' },
        acciones: {
          type: 'ARRAY',
          items: {
            type: 'OBJECT',
            properties: {
              tipo: { type: 'STRING', enum: ['crear', 'editar', 'cancelar', 'completar', 'recordar'] },
              id: { type: 'INTEGER' },
              titulo: { type: 'STRING' },
              inicio: { type: 'STRING' },
              minutos: { type: 'INTEGER' },
              categoria: { type: 'STRING' },
              importancia: { type: 'INTEGER' },
              avisos: { type: 'ARRAY', items: { type: 'INTEGER' } },
              lugar: { type: 'STRING' },
              notas: { type: 'STRING' },
              dato: { type: 'STRING' },
            },
            required: ['tipo'],
          },
        },
      },
      required: ['respuesta', 'acciones'],
    },
  },
};

const api = (c.api || 'https://generativelanguage.googleapis.com/v1beta').replace(/\/$/, '');
return [{ json: {
  listo: true,
  uid: c.uid,
  clave: c.clave,
  url: `${api}/models/${c.modelo}:generateContent`,
  url_respaldo: `${api}/models/${c.respaldo}:generateContent`,
  cuerpo,
} }];

// Interpreta lo que devolvió Gemini (principal o respaldo) y lo deja listo para la base de datos.
const r = $input.first().json;
const previo = $('Preparar consulta').first().json;
const estado = Number(r.statusCode || 0);
const motivo = (r.body && r.body.error && r.body.error.message) || '';

let respuesta = '';
let acciones = [];
if (estado === 200) {
  const partes = (((r.body.candidates || [])[0] || {}).content || {}).parts || [];
  const texto = partes.filter((x) => !x.thought).map((x) => x.text || '').join('').trim();
  try {
    const plan = JSON.parse(texto.replace(/^```(json)?/i, '').replace(/```$/, ''));
    respuesta = String(plan.respuesta || '').trim();
    acciones = Array.isArray(plan.acciones) ? plan.acciones.slice(0, 12) : [];
  } catch (e) {
    respuesta = texto || 'No pude ordenar mis ideas esta vez. ¿Me lo repites con otras palabras?';
  }
} else if (/API key|API_KEY|PERMISSION_DENIED/i.test(motivo) || estado === 401 || estado === 403) {
  respuesta = 'Tu clave de Gemini no funciona. Revísala en Ajustes ▸ Inteligencia.';
} else if (estado === 429) {
  respuesta = 'Llegaste al límite gratuito de Gemini por ahora. Espera un minuto y vuelve a intentarlo.';
} else if (estado === 0) {
  respuesta = 'No pude conectarme con Gemini. Revisa tu conexión a internet.';
} else {
  respuesta = 'Gemini no respondió esta vez (' + estado + '). Inténtalo de nuevo en un momento.';
}

// "tipo" de la IA es la acción; la categoría del evento viaja aparte
acciones = acciones
  .filter((a) => a && typeof a === 'object' && a.tipo)
  .map((a) => {
    const { tipo, categoria, ...resto } = a;
    return { ...resto, accion: tipo, ...(categoria ? { tipo: String(categoria).toLowerCase() } : {}) };
  });

return [{ json: { paquete: JSON.stringify({ uid: previo.uid, respuesta, acciones }) } }];
